bool binarySearch(vector<int>& v, int target) {
int low = 0, high = v.size() - 1;
while (low <= high) {
int mid = ((high - low) / 2) + low;
if (v[mid] == target) {
return true;
}
if (v[mid] > target)
high = mid - 1;
else
low = mid + 1;
}
return false;
}
