void softmax(const double* input, double* output, int length) {
double max_val = input[0];
for (int i = 1; i < length; ++i) {
if (input[i] > max_val) {
max_val = input[i];
}
}
double sum = 0.0;
for (int i = 0; i < length; ++i) {
output[i] = exp(input[i] - max_val);
sum += output[i];
}
for (int i = 0; i < length; ++i) {
output[i] /= sum;
}
}
