using namespace std;
void trainSVM(double* X, int* y,
int n,
int d,
double C,
double lr,
int epochs,
double* w,
double& b) {
for (int j = 0; j < d; j++) w[j] = 0.0;
b = 0.0;
for (int it = 0; it < epochs; it++) {
for (int i = 0; i < n; i++) {
double dot = 0.0;
for (int j = 0; j < d; j++)
dot += w[j] * X[i * d + j];
double margin = y[i] * (dot + b);
if (margin < 1) {
for (int j = 0; j < d; j++) {
w[j] += lr * (C * y[i] * X[i * d + j] - w[j]);
}
b += lr * C * y[i];
} else {
for (int j = 0; j < d; j++) {
w[j] += lr * (-w[j]);
}
}
}
}
